return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=6; plural=(n==0 ? 0 : n==1 ? 1 : n==2 ? 2 : n%100>=3 && n%100<=10 ? 3 : n%100>=11 && n%100<=99 ? 4 : 5);','messages' => ['WooCommerce' => 'ووكومرس','Go to Plugin Search' => 'انتقل إلى البحث عن المكونات الإضافية','Activate %s' => 'تفعيل %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => 'يتطلب <strong>%1$s</strong> تثبيت <strong>%2$s</strong> وتنشيطه. <a href="%4$s">%3$s</a>','Enter your code here' => 'أدخل الكود الخاص بك هنا','Add %s' => 'أضف %s','Remove' => 'يزيل','Order number and receipt will be sent to this email address.' => 'سيتم إرسال رقم الطلب والإيصال إلى عنوان البريد الإلكتروني هذا.','Apartment, unit, building, floor, etc.' => 'شقة، وحدة، مبنى، طابق، الخ.','Shipping phone' => 'هاتف الشحن','Only used for shipping-related questions.' => 'يستخدم فقط للأسئلة المتعلقة بالشحن.','Single step' => 'خطوة واحدة','Click to go to the order summary' => 'انقر للانتقال إلى ملخص الطلب','Cart total:' => 'مجموع العربة:','Proceed to %s' => 'انتقل إلى %s','Proceed to contact' => 'انتقل إلى الاتصال','Proceed to shipping' => 'انتقل إلى الشحن','Proceed to billing' => 'انتقل إلى الفاتورة','Proceed to payment' => 'انتقل إلى الدفع','Shipping method' => 'طريقة الشحن','Additional notes' => 'ملاحظات إضافية','Payment method' => 'طريقة الدفع','Step %1$s of %2$s' => 'الخطوة %1$s من %2$s','Change: %s' => 'التغيير: %s','Not selected yet.' => 'لم يتم التحديد بعد','Same as shipping address' => 'نفس عنوان الشحن','Same as billing address' => 'نفس عنوان الفاتورة','Order summary' => 'ملخص الطلب','Edit cart' => 'تعديل عربة التسوق','Did you mean %s?' => 'هل تقصد %s؟','Change email address to: {suggestion-value}' => 'تغيير عنوان البريد الإلكتروني إلى: {suggestion-value}','This is a required field.' => 'هذا الحقل مطلوب.','This is not a valid email address.' => 'هذا ليس عنوان بريد إلكتروني صالحًا.','This field does not match the related field value.' => 'هذا الحقل لا يتطابق مع قيمة الحقل ذات الصلة.','The CPF number "{cpf_number}" is invalid.' => 'رقم CPF &quot;{cpf_number}&quot; غير صالح.','The CNPJ number "{cnpj_number}" is invalid.' => 'رقم CNPJ &quot;{cnpj_number}&quot; غير صالح.','(Required)' => '(مطلوب)','Checkout Header - Desktop' => 'رأس صفحة الخروج - سطح المكتب','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'عرض عناصر واجهة المستخدم على رأس صفحة الخروج للشاشات الكبيرة. يتم عرضها فقط في حالة استخدام رأس صفحة الخروج للمكون الإضافي.','Checkout Header - Mobile' => 'رأس صفحة الخروج - الجوال','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'عرض عناصر واجهة المستخدم أسفل رأس صفحة الدفع للأجهزة المحمولة. يتم عرضها فقط في حالة استخدام رأس صفحة الدفع للمكون الإضافي.','Checkout Sidebar' => 'شريط الخروج الجانبي','Display widgets on the checkout sidebar after the order summary.' => 'عرض الأدوات على الشريط الجانبي للدفع بعد ملخص الطلب.','Checkout Order Summary' => 'ملخص طلب الخروج','Display widgets inside the order summary at the checkout page.' => 'عرض الأدوات داخل ملخص الطلب في صفحة الخروج.','Checkout Below Place Order' => 'الدفع أدناه وضع الطلب','Display widgets below the place order button at the checkout page.' => 'عرض الأدوات أسفل زر تقديم الطلب في صفحة الخروج.','Checkout Footer' => 'تذييل الخروج','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'عرض عناصر واجهة المستخدم في تذييل الخروج. يتم عرضها فقط في حالة استخدام تذييل الخروج للمكون الإضافي.','Classic' => 'كلاسيكي','Boxed' => 'مُعبأ','Split' => 'ينقسم','Minimalist' => 'الحد الأدنى','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'إضافات Fluid Checkout و Delivery Date من CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p style=";text-align:right;direction:rtl">لقد اكتشفنا أنك تستخدم المكونات الإضافية Delivery &amp; Pickup Date Time for WooCommerce (المجانية والاحترافية) من CodeRockz. تم نقل التكامل مع هذه المكونات الإضافية إلى Fluid Checkout PRO.</p>','Upgrade to PRO' => 'الترقية إلى PRO','Fluid Checkout database updated successfully' => 'تم تحديث قاعدة بيانات Fluid Checkout بنجاح','The database changes where applied successfully.' => 'تتم تغييرات قاعدة البيانات حيث يتم تطبيقها بنجاح.','Dismiss' => 'رفض','Fluid Checkout database update' => 'تحديث قاعدة بيانات Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'قد يلزم إجراء بعض التغييرات على قاعدة البيانات. وكما هو الحال مع أي تحديث، نوصيك <strong>بإجراء نسخة احتياطية كاملة لموقعك على الويب قبل المتابعة</strong> .','Update database' => 'تحديث قاعدة البيانات','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'لا يتوافق Fluid Checkout مع تخطيط الخروج الخاص بـ Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p style=";text-align:right;direction:rtl">يحتاج Fluid Checkout إلى نموذج الخروج الكلاسيكي المستند إلى الرمز المختصر في WooCommerce ليعمل. عند استخدام Divi Builder لتخصيص مظهر وشكل صفحة الخروج، يتم استبدال الرموز المختصرة الكلاسيكية بأدوات مخصصة من Divi Builder لكل جزء من صفحة الخروج. هذه الأدوات المخصصة غير متوافقة مع Fluid Checkout.</p><p style=";text-align:right;direction:rtl"> يرجى تعديل صفحة الخروج الخاصة بك عن طريق استبدال عناصر واجهة المستخدم الرسومية Divi Builder بعنصر واجهة المستخدم الرسومية النصي الذي يحتوي على الرمز المختصر <code>[woocommerce_checkout]</code> .</p>','Edit the checkout page' => 'تعديل صفحة الخروج','Read the documentation.' => 'اقرأ الوثائق.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'يجب تعطيل ميزة الخروج متعدد الخطوات PRO الألمانية عند استخدام Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'عند استخدام Fluid Checkout، تصبح ميزة الخطوات المتعددة من البرنامج الإضافي Germanized PRO غير ضرورية وقد تتسبب في حدوث <strong>أخطاء فادحة أثناء معالجة الطلبات الجديدة</strong> . يُرجى تعطيل ميزة الخطوات المتعددة من Germanized PRO في إعدادات البرنامج الإضافي.','Go to Germanized settings' => 'انتقل إلى الإعدادات الألمانية','Thanks for choosing Fluid Checkout!' => 'شكرًا لاختيارك Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'لقد كنت تستخدم البرنامج المساعد منذ فترة. ما رأيك فيه حتى الآن؟<br> يرجى إعطائنا تقييمًا سريعًا، فنحن نقدر كل جزء من التعليقات ويشجعنا ذلك على الاستمرار في تحسين البرنامج الإضافي :)','Rate the plugin' => 'قم بتقييم البرنامج الإضافي','I need help!' => 'انا بحاجة الى مساعدة!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'قد لا تعمل بعض ميزات WooCommerce Checkout Manager من Quadlayers بالشكل المتوقع عند استخدامها مع Fluid Checkout. اقرأ <a href="%s">وثائقنا</a> للحصول على مزيد من المعلومات والحلول البديلة.','Read documentation' => 'قراءة الوثائق','Don\'t show this again' => 'لا تعرض هذا مرة أخرى','Fluid Checkout PRO' => 'فحص السوائل PRO','More design templates' => 'المزيد من قوالب التصميم','Optimized cart page' => 'صفحة عربة التسوق المُحسّنة','Optimized order received / thank you page' => 'تم تحسين الطلب المستلم / صفحة الشكر','Edit cart contents at checkout page' => 'تعديل محتويات عربة التسوق في صفحة الخروج','Account matching / user matching' => 'مطابقة الحساب / مطابقة المستخدم','Trust symbols on the cart and thank you pages' => 'رموز الثقة على عربة التسوق وصفحات الشكر','More positions for the coupon code on the checkout page' => 'مزيد من المواضع لرمز القسيمة على صفحة الدفع','International phone numbers' => 'أرقام الهاتف الدولية','Gift messages and packing slips' => 'رسائل الهدايا وأوراق التعبئة','Local pickup and in-store collection' => 'الاستلام المحلي والاستلام من المتجر','EU-VAT Assistant' => 'مساعد ضريبة القيمة المضافة في الاتحاد الأوروبي','I already have it – Hide this offer' => 'لدي بالفعل - إخفاء هذا العرض','Activated' => 'تم التفعيل','Address book' => 'دفتر العناوين','Select an image' => 'حدد صورة','Cart layout' => 'تخطيط العربة','Cart optimizations' => 'تحسينات عربة التسوق','Enable cart page optimizations' => 'تمكين تحسينات صفحة عربة التسوق','Header and footer template' => 'قالب الرأس والتذييل','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'يتحكم فيما إذا كان سيتم استخدام رأس وتذييل الصفحة الخالي من التشتيت أو الاحتفاظ برأس وتذييل السمة النشطة حاليًا.','Distraction free header and footer' => 'رأس وتذييل خاليان من التشتيت','Theme\'s header and footer' => 'رأس وتذييل الموضوع','Cart elements' => 'عناصر العربة','Make the order summary stay visible on the cart page while scrolling' => 'اجعل ملخص الطلب مرئيًا على صفحة عربة التسوق أثناء التمرير','Coupon codes' => 'اكواد القسيمة','Hidden' => 'مختفي','Before the cart items section' => 'قبل قسم عناصر عربة التسوق','Inside the cart items section' => 'داخل قسم عناصر عربة التسوق','After the cart items section' => 'بعد قسم عناصر عربة التسوق','Before the shipping section' => 'قبل قسم الشحن','After the shipping section' => 'بعد قسم الشحن','Before the order summary' => 'قبل ملخص الطلب','Inside the order summary' => 'داخل ملخص الطلب','Before the order totals' => 'قبل أن يصل إجمالي الطلب','After the order totals' => 'بعد إجمالي الطلب','After the order summary' => 'بعد ملخص الطلب','Shipping' => 'شحن','Select position where to display the shipping costs and calculator on the cart page.' => 'حدد الموضع الذي تريد عرض تكاليف الشحن والحاسبة فيه على صفحة عربة التسوق.','Display as a cart section' => 'عرض كقسم عربة التسوق','Cross-sells' => 'البيع المتبادل','Select position where to display the cross-sells section on the cart page.' => 'حدد الموضع الذي تريد عرض قسم المبيعات المتبادلة فيه على صفحة عربة التسوق.','Before the cart actions' => 'قبل إجراءات العربة','After the cart actions' => 'بعد إجراءات العربة','Layout of cross-sell items on the cart page.' => 'تخطيط العناصر المتقاطعة للبيع على صفحة عربة التسوق.','Optimized horizontal cross-sells layout' => 'تخطيط محسّن لعمليات البيع المتبادلة الأفقية','Theme\'s cross-sells layout' => 'تخطيط المبيعات المتبادلة للموضوع','Number of cross-sell items to display on the cart page' => 'عدد العناصر التي يتم بيعها بشكل متبادل والتي سيتم عرضها في صفحة عربة التسوق','Add widget areas to the cart page' => 'إضافة مناطق الأدوات إلى صفحة عربة التسوق','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'تُستخدم مناطق الأدوات هذه لإضافة رموز الثقة وشعارات الثقة إلى صفحة عربة التسوق.','Checkout' => 'الدفع','Checkout layout' => 'تخطيط الخروج','Design template' => 'قالب التصميم','Dark mode' => 'الوضع المظلم','Enable dark mode' => 'تمكين الوضع المظلم','Logo image' => 'صورة الشعار','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'اختر صورة لعرضها في رأس صفحة الدفع. ينطبق هذا فقط عند استخدام رأس وتذييل الصفحة الخالي من التشتيت.','Header background color' => 'لون خلفية الرأس','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'اختر لون الخلفية لرأس صفحة الدفع. ينطبق هذا فقط عند استخدام الرأس والتذييل الخاليين من التشتيت.','HTML color value. ie: #f3f3f3' => 'قيمة اللون في HTML. على سبيل المثال: #f3f3f3','Page background color' => 'لون خلفية الصفحة','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'اختر لون الخلفية لصفحة الدفع. يتم تطبيق اللون على عنصر <em>النص</em> .','Footer background color' => 'لون خلفية التذييل','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'اختر لون الخلفية لتذييل صفحة الدفع. ينطبق هذا فقط عند استخدام رأس وتذييل الصفحة الخاليين من التشتيت.','Progress bar' => 'شريط التقدم','Display the checkout progress bar when using multi-step checkout layout' => 'عرض شريط تقدم عملية الدفع عند استخدام تخطيط الدفع متعدد الخطوات','Make the checkout progress bar stay visible while scrolling' => 'جعل شريط تقدم الخروج مرئيًا أثناء التمرير','Express checkout' => 'الدفع السريع','Enable the express checkout section' => 'تمكين قسم الدفع السريع','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'يعرض قسم الخروج السريع عند الخروج عندما تكون بوابات الدفع المدعومة لديها هذه الميزة ممكّنة.','Display express checkout buttons in one line for larger screens' => 'عرض أزرار الدفع السريع في سطر واحد للشاشات الأكبر حجمًا','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'تجاهل الحقول الإضافية المطلوبة عند الدفع باستخدام بوابة دفع سريعة متوافقة','Make the order summary stay visible while scrolling' => 'جعل ملخص الطلب مرئيًا أثناء التمرير','Choose a background color for the order summary section.' => 'اختر لون الخلفية لقسم ملخص الطلب.','Highlight the order totals row in the order summary table' => 'قم بتسليط الضوء على صف إجمالي الطلبات في جدول ملخص الطلبات','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'يكون ذلك مفيدًا للغاية عندما لا يحتوي قسم ملخص الطلب على لون خلفية مميز. وقد ينطبق أيضًا على صفحات عربة التسوق والطلب المستلم وعرض الطلب عند استخدام Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'رابط الإجراء الموجود في ملخص الطلب عند الخروج.','Edit cart link' => 'تعديل رابط عربة التسوق','Cart items count' => 'عدد عناصر عربة التسوق','Link to shop page' => 'رابط لصفحة المتجر','Cart items' => 'عناصر عربة التسوق','Hide cart items errors at the checkout page' => 'إخفاء أخطاء عناصر عربة التسوق في صفحة الخروج','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'لا تعرض رسالة أخطاء عناصر عربة التسوق في أعلى صفحة الدفع. عند إرسال نموذج الدفع لإكمال عملية الشراء، سيتم عرض رسائل الخطأ هذه دائمًا.','Place order' => 'وضع الطلب','Define the position to display "Place order" and terms checkbox section.' => 'قم بتحديد الموضع لعرض قسم &quot;إرسال الطلب&quot; ومربع الاختيار &quot;الشروط&quot;.','Some options might not be compatible with some plugins and themes.' => 'قد لا تكون بعض الخيارات متوافقة مع بعض المكونات الإضافية والمظاهر.','Below the payment section' => 'أسفل قسم الدفع','Below the order summary' => 'أدناه ملخص الطلب','Both below the payment section and the order summary' => 'أسفل قسم الدفع وملخص الطلب','Add widget areas to the checkout page' => 'إضافة مناطق الأدوات إلى صفحة الخروج','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'تُستخدم مناطق الأدوات هذه لإضافة رموز الثقة وشعارات الثقة إلى صفحة الخروج.','Display the coupon codes section title' => 'عرض عنوان قسم أكواد القسيمة','Select position where to display the coupon codes section on the checkout page.' => 'قم باختيار الموضع الذي تريد عرض قسم أكواد القسيمة فيه على صفحة الخروج.','Before the checkout steps' => 'قبل خطوات الخروج','As a substep before payment methods' => 'كخطوة فرعية قبل طرق الدفع','As a substep after payment methods' => 'كخطوة فرعية بعد طرق الدفع','Default button style' => 'نمط الزر الافتراضي','"Add" link button' => 'زر &quot;إضافة&quot; الرابط','Checkout fields' => 'حقول الخروج','Optional fields' => 'الحقول الاختيارية','Hide optional fields behind a link button' => 'إخفاء الحقول الاختيارية خلف زر الرابط','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'من المستحسن إبقاء هذا الخيار محددًا لتقليل عدد حقول الإدخال المفتوحة، <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">اقرأ البحث</a> .','Do not hide "Address line 2" fields behind a link button' => 'لا تقم بإخفاء حقول &quot;سطر العنوان 2&quot; خلف زر الرابط','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'يوصى به فقط عندما يحتاج معظم العملاء بالفعل إلى حقل &quot;سطر العنوان 2&quot;، أو عندما يكون الحصول على عنوان الشحن الصحيح أمرًا بالغ الأهمية (على سبيل المثال، إذا كنت تقوم بتسليم الطعام والمنتجات القابلة للتلف الأخرى).','Billing address' => 'عنوان الفاتورة','Select position where to display the billing address section on the checkout page.' => 'حدد الموضع الذي تريد عرض قسم عنوان الفاتورة فيه على صفحة الخروج.','As a step before shipping' => 'كخطوة قبل الشحن','As a sub-step before the shipping address section' => 'كخطوة فرعية قبل قسم عنوان الشحن','As a sub-step after the shipping address section' => 'كخطوة فرعية بعد قسم عنوان الشحن','As a step after shipping' => 'كخطوة بعد الشحن','As a sub-step before the payment section' => 'كخطوة فرعية قبل قسم الدفع','Force billing and shipping addresses to the same (single section)' => 'فرض عناوين الفواتير والشحن على نفس (قسم واحد)','Checkbox for "Same as shipping/billing address" checked by default' => 'تم تحديد مربع الاختيار &quot;نفس عنوان الشحن/الفوترة&quot; افتراضيًا','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'سيبدأ تحديد مربع الاختيار &quot;نفس عنوان الشحن&quot; افتراضيًا عند عرض قسم عنوان الشحن أولاً.<br> سيبدأ تحديد مربع الاختيار &quot;نفس عنوان الفاتورة&quot; افتراضيًا عند عرض قسم عنوان الفاتورة أولاً.<br> من المستحسن ترك هذا الخيار محددًا لتقليل عدد حقول الإدخال المفتوحة بشكل كبير عند الخروج، <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">اقرأ البحث</a> .','Highlight the billing address section in the checkout form' => 'قم بتسليط الضوء على قسم عنوان الفاتورة في نموذج الخروج','Shipping address' => 'عنوان الشحن','Highlight the shipping address section in the checkout form' => 'قم بتسليط الضوء على قسم عنوان الشحن في نموذج الخروج','Shipping methods' => 'طرق الشحن','Choose in which position to display the shipping methods section.' => 'اختر الموضع الذي تريد عرض قسم طرق الشحن فيه.','Before shipping address' => 'قبل عنوان الشحن','After shipping address' => 'بعد عنوان الشحن','Local pickup' => 'الاستلام المحلي','Removes shipping address section when a local pickup shipping method is selected.' => 'يقوم بإزالة قسم عنوان الشحن عند تحديد طريقة شحن الاستلام المحلية.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'يستبدل عنوان الشحن بموقع نقطة الاستلام عند تحديد طريقة شحن الاستلام المحلية.','Choose which address to save as the shipping address for local pickup orders.' => 'اختر العنوان الذي تريد حفظه كعنوان شحن لطلبات الاستلام المحلية.','Save the selected pickup location' => 'احفظ موقع الاستلام المحدد','Save same as the billing address' => 'احفظ نفس عنوان الفاتورة','Do not save any shipping address' => 'لا تقم بحفظ أي عنوان شحن','Company name field for shipping address' => 'حقل اسم الشركة لعنوان الشحن','Change visibility for the company name field for the shipping address section on the checkout form.' => 'تغيير إمكانية رؤية حقل اسم الشركة لقسم عنوان الشحن في نموذج الخروج.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'إذا تم تعيين الحقل على &quot;اختياري&quot;، وهي حالة الرؤية الافتراضية، فلن يتم تطبيق أي تغييرات للسماح للمكونات الإضافية الأخرى بتطبيق أي تغييرات تحتاج إليها.','Hidden (remove field)' => 'مخفي (إزالة الحقل)','Optional' => 'خياري','Required' => 'مطلوب','Add shipping phone field to the checkout form.' => 'أضف حقل رقم الهاتف الخاص بالشحن إلى نموذج الخروج.','Choose in which step to display the shipping phone field.' => 'اختر الخطوة التي تريد عرض حقل هاتف الشحن فيها.','Contact step' => 'خطوة الاتصال','Billing phone' => 'هاتف الفواتير','Add billing phone field to the checkout form.' => 'أضف حقل رقم الهاتف الخاص بالفواتير إلى نموذج الخروج.','Choose in which step to display the billing phone field.' => 'اختر الخطوة التي تريد فيها عرض حقل هاتف الفاتورة.','Show country code beside the flag' => 'إظهار رمز الدولة بجانب العلم','Show an example of a valid phone number inside phone fields' => 'إظهار مثال لرقم هاتف صالح داخل حقول الهاتف','Do not change placeholders' => 'لا تغير العناصر النائبة','Show if not defined' => 'إظهار إذا لم يتم تعريفه','Always show' => 'اظهر دائما','Order notes' => 'ملاحظات الطلب','Define the visibility of the additional order notes field.' => 'قم بتحديد إمكانية رؤية حقل ملاحظات الطلب الإضافية.','Gift options' => 'خيارات الهدايا','Allow customers to add a gift message and other gift related options to the order.' => 'السماح للعملاء بإضافة رسالة هدية وخيارات أخرى متعلقة بالهدية إلى الطلب.','Display the gift message as part of the order details table instead of a separate section' => 'عرض رسالة الهدية كجزء من جدول تفاصيل الطلب بدلاً من قسم منفصل','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'يؤثر هذا الخيار على صفحة تأكيد الطلب (صفحة الشكر) وتفاصيل الطلب على صفحات الحساب ورسائل البريد الإلكتروني وأوراق التعبئة.','Account matching' => 'مطابقة الحساب','Enable the account matching feature' => 'تمكين ميزة مطابقة الحساب','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'ربط طلبات العميل الضيف بحسابه الحالي عندما يكون هناك حساب موجود بالفعل يحتوي على تفاصيل الاتصال الخاصة بالعميل.','Display message when an account exists with the email address provided' => 'عرض الرسالة عند وجود حساب باستخدام عنوان البريد الإلكتروني المقدم','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'يستبدل حقول إنشاء الحساب بإشعار وخيار لتسجيل الدخول. في بعض السياقات، قد يكون من المستحسن ترك هذا الخيار معطلاً لحماية خصوصية العملاء.','Dashboard' => 'لوحة القيادة','Integrations' => 'التكاملات','License keys' => 'مفاتيح الترخيص','Visit our website for more information about our plugins and add-ons.' => 'قم بزيارة موقعنا الإلكتروني للحصول على مزيد من المعلومات حول المكونات الإضافية لدينا.','Order pay page' => 'صفحة طلب الدفع','Order pay' => 'طلب الدفع','Enable order pay page optimizations' => 'تمكين تحسينات صفحة دفع الطلب','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'تغيير تخطيط صفحة دفع الطلبات للطلبات الموجودة التي تنتظر الدفع من العميل.','Add widget areas to the order pay page' => 'إضافة مناطق الأدوات إلى صفحة دفع الطلب','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'تُستخدم مناطق الأدوات هذه لإضافة رموز الثقة وشعارات الثقة إلى صفحة دفع الطلب.','Thank you page & order details layout' => 'تخطيط صفحة الشكر وتفاصيل الطلب','Order details optimizations' => 'تحسينات تفاصيل الطلب','Enable thank you page and order details optimizations' => 'تمكين تحسينات صفحة الشكر وتفاصيل الطلب','Changes the layout of order details on the thank you page and account pages.' => 'تغيير تخطيط تفاصيل الطلب على صفحة الشكر وصفحات الحساب.','Enable order details customizations on email notifications' => 'تمكين تخصيصات تفاصيل الطلب في إشعارات البريد الإلكتروني','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'عرض أقسام جديدة وتغيير ترتيب الأقسام في إشعارات البريد الإلكتروني. تظل أنماط تفاصيل الترتيب في إشعارات البريد الإلكتروني دون تغيير.','Thank you page' => 'صفحة الشكر','These options affect the thank you page, also known as order received or order confirmation pages.' => 'تؤثر هذه الخيارات على صفحة الشكر، والمعروفة أيضًا بصفحات الطلب المستلم أو تأكيد الطلب.','Order details layout' => 'تخطيط تفاصيل الطلب','Display the order details with wide layout on the thank you page' => 'عرض تفاصيل الطلب بتصميم واسع على صفحة الشكر','Add widget areas to the thank you page' => 'إضافة مناطق الأدوات إلى صفحة الشكر','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'تُستخدم مناطق الأدوات هذه لإضافة رموز الثقة وشعارات الثقة إلى صفحة الشكر.','Order actions' => 'ترتيب الإجراءات','Choose in which position to display the order actions.' => 'اختر الموضع الذي تريد عرض إجراءات الطلب فيه.','Inside the order overview' => 'داخل نظرة عامة على الطلب','After the order overview' => 'بعد نظرة عامة على الطلب','After order sections' => 'أقسام ما بعد الطلب','Order status' => 'حالة الطلب','Display the order status progress bar' => 'عرض شريط تقدم حالة الطلب','Choose in which position to display the section.' => 'اختر الموضع الذي تريد عرض القسم فيه.','After the order overview and payment instructions' => 'بعد نظرة عامة على الطلب وتعليمات الدفع','Before the order items section' => 'قبل قسم عناصر الطلب','Inside the order items section' => 'داخل قسم عناصر الطلب','After the order items section' => 'بعد قسم عناصر الطلب','On the sidebar' => 'على الشريط الجانبي','Order downloads' => 'طلب التنزيلات','Gift message' => 'رسالة هدية','Tools' => 'أدوات','Troubleshooting' => 'استكشاف الأخطاء وإصلاحها','Debug options' => 'خيارات التصحيح','Debug mode' => 'وضع التصحيح','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'يؤثر استخدام وضع التصحيح على أداء موقع الويب. استخدم هذا الخيار فقط أثناء استكشاف الأخطاء وإصلاحها.','Load unminified assets' => 'تحميل الأصول غير المصغرة','Enhanced select fields' => 'تحسين اختيار الحقول','Fix automatic zoom-in on form fields' => 'إصلاح التكبير التلقائي لحقول النموذج','Set <code>font-size</code> inside form fields to 16px' => 'تعيين <code>font-size</code> داخل حقول النموذج إلى 16 بكسل','Fluid Checkout' => 'الدفع السائل','Settings' => 'إعدادات','Support' => 'يدعم','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">قم بالترقية إلى PRO</a> لفتح المزيد من الخيارات.','(PRO)' => '(محترف)','(experimental)' => '(تجريبي)','Please verify your phone number.' => 'يرجى التحقق من رقم هاتفك.','The Bluehost Plugin' => 'إضافة Bluehost','Custom fields' => 'الحقول المخصصة','Enable custom shipping email field' => 'تمكين حقل البريد الإلكتروني للشحن المخصص','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'عند تمكين هذا الخيار، سيتم إضافة حقل البريد الإلكتروني للشحن من مكون Bluehost إلى نموذج الخروج.','Captcha Pro by BestWebSoft' => 'Captcha Pro من BestWebSoft','Captcha position' => 'موضع الكابتشا','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'حدد الموضع الذي سيتم عرض قسم الكابتشا فيه. قد لا تعمل بعض المواضع وفقًا لنوع الكابتشا المختار.','Selecting a pickup point is required before proceeding.' => 'من الضروري تحديد نقطة الاستلام قبل المتابعة.','Pickup point' => 'نقطة الإلتقاط','Pickup point not selected yet.' => 'لم يتم تحديد نقطة الاستلام بعد.','Pickup point:' => 'نقطة الاستلام:','Mailchimp for WooCommerce' => 'Mailchimp لـ WooCommerce','Subscribe checkbox' => 'مربع الاختيار للإشتراك','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'تجاوز موضع مربع الاختيار الخاص بالاشتراك في صفحة الخروج وعرضه دائمًا في خطوة الاتصال','Before Shipping Address' => 'قبل عنوان الشحن','(originally "%s")' => '(في الأصل &quot;%s&quot;)','After Shipping Address' => 'بعد عنوان الشحن','Selecting a collection point is required when shipping with FermoPoint.' => 'يعد اختيار نقطة التجميع أمرًا ضروريًا عند الشحن مع FermoPoint.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'إذا تم تحديد هذا المربع، يتم إعلام المستخدمين بالأخطاء المطبعية في البريد الإلكتروني. (تم تعطيل هذه الميزة لأن Fluid Checkout يوفر هذه الميزة. لن تسري التغييرات على هذا الخيار)','Enable Mail Check: (disabled feature)' => 'تمكين التحقق من البريد: (ميزة معطلة)','Carrier:' => 'الناقل:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - التسويق عبر البريد الإلكتروني باستخدام WooCommerce','Sign up checkbox position' => 'موضع مربع الاختيار للتسجيل','Move the sign up checkbox to the contact step' => 'نقل مربع الاختيار الخاص بالتسجيل إلى خطوة الاتصال','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'عند تمكين هذا الخيار، سيتم نقل مربع الاختيار إلى خطوة جهة الاتصال بشكل مستقل عن موقع العرض المحدد في إعدادات البرنامج الإضافي Sendinblue.','Theme Betheme' => 'ثيم بيثيم','Checkout progress' => 'تقدم عملية الدفع','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'قم بإخراج قسم خطوات الخروج من Betheme على صفحات الخروج وسلة التسوق والطلب المستلم.','Theme Fennik' => 'ثيم فينيك','Breadcrumbs' => 'فتات الخبز','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'إخراج قسم فتات الخبز من قالب Fennik عند استخدام رأس وتذييل Fluid Checkout.','Theme Go' => 'الموضوع اذهب','My account layout' => 'تخطيط حسابي','Enable wide layout on "My account" page.' => 'تمكين التخطيط الواسع في صفحة &quot;حسابي&quot;.','Theme Impreza' => 'ثيم امبريزا','Header' => 'رأس الصفحة','Spacing for site header at the checkout page (in pixels)' => 'المسافة بين عناوين الموقع في صفحة الخروج (بالبكسل)','Only applicable when using the Impreza theme header at the checkout page.' => 'ينطبق فقط عند استخدام رأس موضوع Impreza في صفحة الخروج.','Theme Kapee' => 'ثيم كابي','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'قم بإخراج قسم خطوات الخروج من قالب Kapee على صفحات الخروج وسلة التسوق والطلب المستلم.','Theme Porto' => 'ثيم بورتو','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'قم بإخراج قسم خطوات الخروج من قالب بورتو على صفحات الخروج وسلة التسوق والطلب المستلم.','Theme Pressmart' => 'ثيم بريس مارت','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'قم بإخراج قسم خطوات الخروج من قالب Pressmart على صفحات الخروج وسلة التسوق والطلب المستلم.','Theme The Gem' => 'الموضوع الجوهرة','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'إخراج قسم خطوات الخروج من قالب The Gem عند استخدام رأس وتذييل الخروج السلس.','Theme Woodmart' => 'ثيم وود مارت','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'إخراج قسم خطوات الخروج من قالب Woodmart عند استخدام رأس وتذييل الخروج السلس.','Checkout options' => 'خيارات الدفع','Disable the theme checkout options' => 'تعطيل خيارات الخروج من السمة','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'يتم تعطيل خيارات عرض صورة المنتج وحقل الكمية وزر الإزالة والرابط إلى صفحة المنتج المضافة بواسطة السمة بشكل افتراضي.','Theme Atomion' => 'ثيم اتوميون','Order progress' => 'تقدم الطلب','Display order progress from the theme' => 'عرض تقدم الطلب من الموضوع','Display the form field labels visible on the page' => 'عرض تسميات حقول النموذج المرئية على الصفحة','It is recommended to keep this option enabled for a better user experience.' => 'من المستحسن إبقاء هذا الخيار ممكّنًا للحصول على تجربة مستخدم أفضل.','Theme ZK Nito' => 'ثيم ZK Nito','Add extra fields to the checkout form' => 'إضافة حقول إضافية إلى نموذج الخروج','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'يضيف حقل بريد إلكتروني للشحن ورقم هاتف الشحن إلى قسم عنوان الشحن.','Go to the home page' => 'انتقل إلى الصفحة الرئيسية','Skip to content' => 'انتقل إلى المحتوى','Create an account' => 'إنشاء حساب','Log in to your account' => 'تسجيل الدخول إلى حسابك','Already have an account?' => 'هل لديك حساب بالفعل؟','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'تم تسجيل الدخول باسم %1$s. <a href="%2$s">تسجيل الخروج</a>','Your order has a total amount due of %s. No further payment is needed.' => 'يبلغ إجمالي المبلغ المستحق على طلبك %s. لا يلزم دفع أي مبلغ إضافي.','Close and continue with checkout' => 'إغلاق ومتابعة الدفع','Continue' => 'يكمل','Parcel terminal' => 'محطة الطرود','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p style=";text-align:right;direction:rtl">لقد تم استبدال هذه الأداة بـ Fluid Checkout.</p><p style=";text-align:right;direction:rtl"> عند استخدام Fluid Checkout، تحتاج صفحة الخروج إلى استخدام الرمز المختصر الأصلي لـ WooCommerce <code>[woocommerce_checkout]</code> للعمل بشكل صحيح.</p><p style=";text-align:right;direction:rtl"> لمزيد من المعلومات، تفضل بزيارة وثائق Fluid Checkout.</p>','Theme The7' => 'الموضوع السابع','Additional header sections' => 'أقسام رأسية إضافية','Output additional header sections if enabled in the theme settings.' => 'إخراج أقسام رأسية إضافية إذا تم تمكين ذلك في إعدادات السمة.','More information' => 'مزيد من المعلومات','Pick a Locker' => 'اختر خزانة','Page template' => 'قالب الصفحة','Use `Order confirmation` page template for block-based themes' => 'استخدم قالب صفحة &quot;تأكيد الطلب&quot; للموضوعات القائمة على الكتل','Only applies when using a block-based theme.' => 'ينطبق فقط عند استخدام سمة تعتمد على الكتلة.','WooCommerce Stripe Gateway' => 'بوابة WooCommerce Stripe','Payment form' => 'نموذج الدفع','Apply styles to the Stripe payment form fields' => 'تطبيق الأنماط على حقول نموذج الدفع Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'عند تفعيلها، ستُطبّق Fluid Checkout أنماطًا مُحسّنة للتوافق مع الإضافة. قد ترغب في تعطيل هذه الميزة إذا كنت تستخدم أنماطًا مُخصّصة لحقول نموذج دفع Stripe.','Theme Nyture' => 'موضوع الطبيعة','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'قم بإخراج قسم خطوات الخروج من سمة Nyture عند استخدام Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'يتيح للعملاء إجراء الدفعات الخاصة بالطلبات التي تم إنشاؤها يدويًا بواسطة مسؤول المتجر أو التي لم تكتمل أثناء الخروج.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'المكون الإضافي WooCommerce Checkout Manager من Quadlayers غير متوافق مع Fluid Checkout','Company name field for billing address' => 'حقل اسم الشركة لعنوان الفاتورة','Change visibility for the company name field for the billing address section on the checkout form.' => 'تغيير رؤية حقل اسم الشركة لقسم عنوان الفاتورة في نموذج الخروج.','Theme Bookshelf' => 'رف كتب موضوعي','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'قم بإخراج قسم خطوات الخروج من سمة Bookshelf عند استخدام Fluid Checkout.','Account password' => 'كلمة مرور الحساب','An account will be created with the information provided at checkout when completing the order.' => 'سيتم إنشاء حساب بالمعلومات المقدمة عند إتمام الطلب.','Choose the style of the progress bar.' => 'اختر نمط شريط التقدم.','Bars' => 'الحانات','Theme Ireca' => 'ثيم إيريكا','WooCommerce page layout' => 'تخطيط صفحة WooCommerce','Force wide layout on WooCommerce pages' => 'فرض تخطيط واسع على صفحات WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'يضمن هذا عدم تضييق قسم المحتوى بشكل كبير على صفحات WooCommerce بما في ذلك صفحات الخروج، وسلة التسوق، والطلب المستلم، ودفع الطلب، والحساب.','WooCommerce Smart Coupons' => 'كوبونات ووكومرس الذكية','Position on checkout page' => 'الموضع على صفحة الخروج','Choose where to display the available coupons section on the checkout page.' => 'اختر مكان عرض قسم القسائم المتوفرة على صفحة الخروج.','Before the progress bar' => 'قبل شريط التقدم','After the progress bar' => 'بعد شريط التقدم','Before coupon codes section' => 'قبل قسم أكواد الكوبون','Format phone numbers according to the rules for each country.' => 'تنسيق أرقام الهاتف وفقًا للقواعد الخاصة بكل بلد.','Use precise phone number validation' => 'استخدم التحقق الدقيق من رقم الهاتف','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'هذه ميزة تجريبية وقد لا تعمل كما هو متوقع في جميع الإعدادات. استخدمها بحذر.','Phone number validation types used when precise validation is enabled.' => 'أنواع التحقق من صحة رقم الهاتف المستخدمة عند تمكين التحقق الدقيق.','Mobile' => 'متحرك','Fixed line' => 'خط ثابت','Toll free' => 'رقم مجاني','Contact' => 'اتصال','Multi step' => 'خطوات متعددة','2 columns' => 'عمودان','1 column' => 'عمود واحد','Before checkout steps' => 'خطوات ما قبل إتمام عملية الشراء','Or' => 'أو','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'عند استخدام تخطيط الدفع <em>&quot;عمود واحد&quot;</em> ، يتم دائمًا تعيين هذا الخيار على <em>&quot;خطوات ما قبل الدفع&quot;</em> وينطبق أيضًا على عرض سطح المكتب.','Position for the extra order summary section on mobile.' => 'موضع قسم ملخص الطلب الإضافي على الهاتف المحمول.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'لا ينطبق خيار <em>&quot;في رأس الموقع&quot;</em> إلا عند استخدام رأس الموقع الخالي من عوامل التشتيت.','On the site header (requires distraction-free header)' => 'في رأس الموقع (يتطلب رأسًا خاليًا من عوامل التشتيت)','Initial state for the expansible order summary section on mobile.' => 'الحالة الأولية لقسم ملخص الطلب القابل للتوسيع على الهاتف المحمول.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'نوصي بتعيينه على أنه <em>موسع</em> للدول التالية بسبب المتطلبات التنظيمية: <strong>ألمانيا</strong> ، <strong>النمسا</strong> ، <strong>سويسرا</strong> ، <strong>هولندا</strong> ، <strong>بولندا</strong> ، <strong>بلجيكا</strong> <strong>وفرنسا</strong> .','Collapsed' => 'مُنهار','Expanded' => 'موسع','Do not show' => 'لا تظهر','yes' => 'نعم','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'قد يُفرض حقل رقم الهاتف الخاص بالشحن كحقل إلزامي إذا كان قسم عنوان الفوترة معروضًا بعد قسم عنوان الشحن، وكان حقل رقم الهاتف الخاص بالفوترة مُحددًا كحقل إلزامي. هذا ضروري لضمان إمكانية نسخ عنوان الشحن إلى عنوان الفوترة عند تحديد هذا الخيار، وإلا فقد لا يتمكن العميل من إكمال نموذج الدفع.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'قد يُفرض إدخال رقم هاتف الفاتورة كحقل إلزامي إذا عُرض قسم عنوان الفاتورة قبل قسم عنوان الشحن، وكان رقم هاتف الشحن مُحددًا كحقل إلزامي. هذا ضروري لضمان إمكانية نسخ عنوان الشحن إلى عنوان الفاتورة عند تحديد هذا الخيار، وإلا فقد لا يتمكن العميل من إكمال عملية الدفع.','Settings profiles' => 'إعدادات الملفات الشخصية','Settings profile' => 'ملف تعريف الإعدادات','You do not have permission to perform this action.' => 'ليس لديك إذن للقيام بهذا الإجراء.','You do not have permission to activate plugins.' => 'ليس لديك إذن لتفعيل الإضافات.','Missing plugin.' => 'المكون الإضافي مفقود.','Plugin activated.' => 'تم تفعيل الإضافة.','The following changes will be applied:' => 'سيتم تطبيق التغييرات التالية:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'منذ إصدار Fluid Checkout 5.0، يتم حفظ الإعدادات بطريقة مختلفة. لا تزال الخيارات القديمة مخزنة في قاعدة البيانات للسماح بالرجوع إلى الإصدارات السابقة عند الحاجة.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'يعمل متجرك منذ حوالي أسبوعين بالإعدادات الجديدة، لذا يمكنك حذف الخيارات القديمة المخزنة في قاعدة البيانات. يُرجى العلم أنه بعد عملية الحذف، إذا احتجتَ إلى الرجوع إلى الإصدارات السابقة من الإضافة، فسيتم استخدام القيم الافتراضية لجميع الإعدادات.','Fluid Checkout settings cleanup' => 'تنظيف إعدادات فحص السوائل','Delete leftover options' => 'حذف الخيارات المتبقية','Help us improve Fluid Checkout' => 'ساعدنا في تحسين عملية فحص السوائل','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'شارك تقارير بيئة الموقع بشكل مجهول مع Fluid Checkout للحصول على دعم أسرع ومساعدتنا في تحسين التوافق وقياس التأثير. لا تتضمن هذه التقارير أي بيانات خاصة بالعملاء أو المستخدمين أو أي بيانات حساسة. يمكنك اختيار ما تتم مشاركته في أي وقت من إعدادات الأدوات.','Enable site environment reports' => 'تفعيل تقارير بيئة الموقع','Review settings' => 'إعدادات المراجعة','This preview has expired. Reload the admin page to start a new preview.' => 'انتهت صلاحية هذه المعاينة. أعد تحميل صفحة الإدارة لبدء معاينة جديدة.','Preview expired' => 'انتهت فترة المعاينة','Orders cannot be placed in the preview.' => 'لا يمكن تقديم الطلبات في مرحلة المعاينة.','Logging in is not available in the preview.' => 'لا تتوفر خاصية تسجيل الدخول في المعاينة.','Accounts cannot be created in the preview.' => 'لا يمكن إنشاء حسابات في المعاينة.','Requests to other sites are blocked in the preview.' => 'يتم حظر الطلبات إلى مواقع أخرى في المعاينة.','Processing…' => 'يعالج…','Something went wrong. Please try again.' => 'حدث خطأ ما. يرجى المحاولة مرة أخرى.','Activate plugin' => 'تفعيل الإضافة','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - حزمة الدفع الكاملة','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'جميع ميزات النسخة الاحترافية + جميع الإضافات، بسعر واحد. قوالب تصميم، صفحات سلة التسوق وصفحات استلام الطلبات مُحسّنة، ومطابقة الحسابات، وغير ذلك الكثير.','Optimized order pay page' => 'صفحة دفع الطلبات المحسّنة','Express checkout buttons from supported payment methods' => 'أزرار الدفع السريع من طرق الدفع المدعومة','Delayed account creation' => 'إنشاء حساب متأخر','Address autocomplete with Google Maps APIs' => 'إكمال العناوين تلقائيًا باستخدام واجهات برمجة تطبيقات خرائط جوجل','Multiple saved addresses with the address book' => 'عناوين متعددة محفوظة في دفتر العناوين','EU-VAT assistant' => 'مساعد ضريبة القيمة المضافة في الاتحاد الأوروبي','Hide this section' => 'إخفاء هذا القسم','Learn more' => 'يتعلم أكثر','Get early access' => 'احصل على وصول مبكر','Activate add-on' => 'تفعيل الإضافة','Get more out of your checkout journey' => 'استفد أكثر من تجربة الدفع الخاصة بك','Test API key' => 'مفتاح اختبار واجهة برمجة التطبيقات','Guided setup' => 'الإعداد الموجه','Options' => 'خيارات','Set up layout and design on the <a href="%s">checkout options</a>.' => 'قم بإعداد التخطيط والتصميم <a href="%s">لخيارات الدفع</a> .','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'قم بتمكين خاصية الدفع كضيف و/أو راجع <a href="%s">إعدادات حسابات العملاء</a> .','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'قم بتفعيل صفحات <a href="%1$s">سلة التسوق</a> المحسّنة، <a href="%2$s">وصفحات الشكر</a> ، وصفحات <a href="%3$s">دفع الطلبات</a> .','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'فعّل <a href="%s">خاصية الإكمال التلقائي للعناوين</a> من خرائط جوجل.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'تفعيل حفظ عناوين متعددة باستخدام <a href="%s">دفتر العناوين</a> .','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'تحقق مما إذا كانت هناك أي <a href="%s">خيارات تكامل</a> متاحة للقالب أو الإضافات الأخرى التي قمت بتثبيتها.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'احصل على دعم أسرع وساعدنا في تحسين التوافق وقياس التأثير. <a href="%s">فعّل خاصية تتبع الاستخدام</a> من إعدادات الأدوات.','Missing settings tab.' => 'علامة تبويب الإعدادات مفقودة.','Getting started' => 'ابدء','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>ممتاز! صفحة الدفع الخاصة بك تعمل الآن على منصة Fluid Checkout.</strong> إليك بعض الخطوات للبدء:','Completed' => 'مكتمل','Preview report data' => 'معاينة بيانات التقرير','Send now' => 'أرسل الآن','Auto-detect' => 'الكشف التلقائي','Afrikaans' => 'الأفريكانية','Albanian' => 'الألبانية','Amharic' => 'الأمهرية','Arabic' => 'عربي','Armenian' => 'الأرمنية','Azerbaijani' => 'الأذرية','Basque' => 'الباسكية','Belarusian' => 'بيلاروسي','Bengali' => 'البنغالية','Bosnian' => 'البوسني','Bulgarian' => 'البلغارية','Burmese' => 'البورميين','Catalan' => 'الكاتالونية','Chinese' => 'الصينية','Chinese (Simplified)' => 'الصينية (المبسطة)','Chinese (Hong Kong)' => 'الصينية (هونغ كونغ)','Chinese (Traditional)' => 'الصينية (التقليدية)','Croatian' => 'الكرواتية','Czech' => 'التشيك','Danish' => 'دانماركي','Dutch' => 'هولندي','English' => 'إنجليزي','English (Australian)' => 'الإنجليزية (الأسترالية)','English (Great Britain)' => 'الإنجليزية (بريطانيا العظمى)','Estonian' => 'الإستونية','Farsi' => 'الفارسية','Finnish' => 'الفنلندية','Filipino' => 'فلبيني','French' => 'فرنسي','French (Canadian)' => 'الفرنسية (الكندية)','Galician' => 'الجاليكية','Georgian' => 'جورجي','German' => 'الألمانية','Greek' => 'اليونانية','Gujarati' => 'الغوجاراتية','Hebrew' => 'العبرية','Hindi' => 'الهندية','Hungarian' => 'المجرية','Icelandic' => 'الأيسلندية','Indonesian' => 'إندونيسيا','Italian' => 'إيطالي','Japanese' => 'اليابانية','Kannada' => 'الكانادا','Kazakh' => 'الكازاخستاني','Khmer' => 'الخمير','Korean' => 'كوري','Kyrgyz' => 'قيرغيزستان','Lao' => 'لاو','Latvian' => 'اللاتفية','Lithuanian' => 'الليتواني','Macedonian' => 'المقدوني','Malay' => 'الملايو','Malayalam' => 'المالايالامية','Marathi' => 'الماراثية','Mongolian' => 'المنغولي','Nepali' => 'النيبالية','Norwegian' => 'النرويجية','Polish' => 'بولندي','Portuguese' => 'البرتغالية','Portuguese (Brazil)' => 'البرتغالية (البرازيل)','Portuguese (Portugal)' => 'البرتغالية (البرتغال)','Punjabi' => 'البنجابية','Romanian' => 'روماني','Russian' => 'الروسية','Serbian' => 'الصربية','Sinhalese' => 'السنهالية','Slovak' => 'سلوفاكيا','Slovenian' => 'السلوفيني','Spanish' => 'الأسبانية','Spanish (Latin America)' => 'الإسبانية (أمريكا اللاتينية)','Swahili' => 'السواحيلية','Swedish' => 'السويدية','Tamil' => 'التاميل','Telugu' => 'التيلجو','Thai' => 'تايلاندي','Turkish' => 'تركي','Ukrainian' => 'الأوكرانية','Urdu' => 'الأردية','Vietnamese' => 'الفيتناميين','Zulu' => 'الزولو','Google address autocomplete' => 'إكمال عناوين جوجل تلقائيًا','Google Places API version' => 'إصدار واجهة برمجة تطبيقات أماكن جوجل','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'اختر إصدار واجهة برمجة تطبيقات Google Places الذي ترغب باستخدامه. نوصي بالانتقال إلى واجهة برمجة تطبيقات Places الجديدة في أقرب وقت ممكن.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'نوصي باستخدام &quot;واجهة برمجة تطبيقات الأماكن (الجديدة)&quot;، حيث ستنقل جوجل اعتبارًا من 1 مارس 2025 إصدار &quot;واجهة برمجة تطبيقات الأماكن (القديمة)&quot; إلى حالة &quot;قديمة&quot;، مما يعني أنه لن يكون بإمكانك تفعيل هذه الخدمة لمفاتيح واجهة برمجة التطبيقات الجديدة، وأن هذا الإصدار من واجهة برمجة التطبيقات سيتوقف عن العمل نهائيًا. أما الحسابات الحالية التي تستخدم واجهة برمجة التطبيقات القديمة، فستستمر في العمل دون انقطاع.','(Recommended)' => '(مُستَحسَن)','Google API key' => 'مفتاح واجهة برمجة تطبيقات جوجل','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'ألصق مفتاح واجهة برمجة تطبيقات جوجل (Google API) الخاص بك، واستخدم زر الاختبار للتأكد من عمله على هذا الموقع. تأكد من أن المفتاح صالح ومسموح به لنطاقك، وإلا فقد يتم حظر حقل العنوان، مما يمنع العملاء من إتمام طلباتهم.','Enable Google address autocomplete' => 'تفعيل خاصية الإكمال التلقائي لعناوين جوجل','Enable address autocompletion using the Google Maps APIs.' => 'قم بتفعيل خاصية الإكمال التلقائي للعناوين باستخدام واجهات برمجة تطبيقات خرائط جوجل.','Google API language' => 'لغة واجهة برمجة تطبيقات جوجل','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'ستُستخدم هذه اللغة لعرض اقتراحات عناوين واجهة برمجة تطبيقات Google Places، كما سيتم إكمال العناوين تلقائيًا بهذه اللغة.','Result types' => 'أنواع النتائج','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'اترك هذا الحقل فارغًا لقبول أي نوع من النتائج، مما يؤدي عادةً إلى نتائج مطابقة أفضل. <a href="%s" target="_blank">راجع الوثائق لمزيد من التفاصيل</a> .<br> حدد ما يصل إلى 5 أنواع من نتائج البحث عن العناوين لعرضها في حقول الإكمال التلقائي للعناوين.<br> قم بزيارة وثائق خرائط جوجل لمعرفة المزيد عن <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">الأنواع المدعومة</a> .','Result types (Legacy API)' => 'أنواع النتائج (واجهة برمجة التطبيقات القديمة)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'ما نوع نتائج البحث عن العناوين التي يجب إرجاعها عند استخدام واجهة برمجة تطبيقات الأماكن (القديمة)؟<br> قم بزيارة وثائق واجهة برمجة تطبيقات Google Places القديمة لمعرفة المزيد حول <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">الأنواع المدعومة</a> .','Company fields' => 'مجالات الشركة','Enable autocomplete for the company name if available' => 'فعّل خاصية الإكمال التلقائي لاسم الشركة إن وجدت','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'قم بتمكين خاصية الإكمال التلقائي لحقل الشركة بمعلومات اسم الشركة عند استرجاعها من واجهات برمجة تطبيقات خرائط جوجل.','Business search' => 'البحث عن الأعمال','Enable search for businesses in the company field' => 'تفعيل البحث عن الشركات في حقل الشركة','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'قم بتمكين اقتراح العناوين المرتبطة بنشاط تجاري عند الكتابة في حقل الشركة، ثم أكمل جميع حقول العناوين تلقائيًا عند تحديد نشاط تجاري من الاقتراحات.','Company result types' => 'أنواع نتائج الشركات','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'حدد ما يصل إلى 5 أنواع من نتائج البحث عن العناوين لعرضها في حقول الشركة عند الإكمال التلقائي.<br> القيمة الموصى بها هي <code>establishment</code> ، والذي يشمل معظم أنواع الأعمال.<br> اترك هذا الحقل فارغًا لقبول أي نوع من النتائج، بما في ذلك النتائج غير المتعلقة بالشركات.<br> قم بزيارة وثائق خرائط جوجل لمعرفة المزيد عن <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">الأنواع المدعومة</a> .','Google logo' => 'شعار جوجل','Show text and logo "Powered by Google"' => 'عرض النص والشعار &quot;مدعوم من جوجل&quot;','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'عند تحديد الخيار، سيتم عرض النص والشعار &quot;مدعوم من Google&quot; في أسفل مربع اقتراحات الإكمال التلقائي للعناوين.','Brasil API address autocomplete' => 'إكمال تلقائي لعناوين واجهة برمجة تطبيقات البرازيل','Brasil API' => 'واجهة برمجة التطبيقات البرازيلية','Enable Brasil API address autocomplete for CEP fields' => 'تفعيل خاصية الإكمال التلقائي لعناوين واجهة برمجة تطبيقات البرازيل لحقول CEP','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'استخدم واجهة برمجة تطبيقات البرازيل (Brasil API) لاسترداد العناوين وتعبئتها تلقائيًا باستخدام حقل الرمز البريدي (CEP). هذا ينطبق فقط على العناوين البرازيلية.','API version' => 'إصدار واجهة برمجة التطبيقات','Choose which version of the Brasil API CEP method to use.' => 'اختر أي إصدار من طريقة Brasil API CEP تريد استخدامه.','Address book migration' => 'نقل دفتر العناوين','WooCommerce addresses' => 'عناوين ووكومرس','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'انسخ عناوين الشحن والفواتير الموجودة من WooCommerce إلى دفتر عناوين العملاء.','Enable the address book feature' => 'قم بتفعيل ميزة دفتر العناوين','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'السماح للعملاء بحفظ عناوين متعددة وتحديد العنوان الافتراضي الذي سيتم استخدامه للشحن والفواتير.','Address labels' => 'ملصقات العناوين','Allow customers to add a custom label for each address' => 'السماح للعملاء بإضافة ملصق مخصص لكل عنوان','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'تُسهّل ملصقات العناوين على العملاء التمييز بين عناوينهم المحفوظة (مثلاً: &quot;منزل أمي&quot;). ملصقات العناوين خاصة بالعملاء، ولن تُعرض أو تُطبع على صفحة تفاصيل الطلب أو الفواتير.','Display layout' => 'تخطيط العرض','Choose how saved addresses are displayed at checkout and on the cart.' => 'اختر كيفية عرض العناوين المحفوظة عند إتمام عملية الشراء وفي سلة التسوق.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'ينطبق هذا العرض عند إتمام عملية الشراء وفي سلة التسوق. يتم استخدام تصميم البطاقات دائمًا للعناوين المحفوظة في صفحة الحساب.','Address cards' => 'بطاقات العناوين','Address list' => 'قائمة العناوين','Dropdown field' => 'حقل القائمة المنسدلة','Address search' => 'البحث عن عنوان','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'اعرض فلتر البحث عن العناوين في واجهة المستخدم عندما يكون لدى العميل هذا العدد على الأقل من العناوين المحفوظة المتاحة.','Not used when display layout is set to dropdown field.' => 'لا يُستخدم عند ضبط تخطيط العرض على حقل القائمة المنسدلة.','Addresses' => 'العناوين','Enable cart page optimizations to see more options' => 'فعّل تحسينات صفحة سلة التسوق لعرض المزيد من الخيارات','Sticky order summary' => 'ملخص الطلب الثابت','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'حدد موضع عرض قسم أكواد الخصم في صفحة سلة التسوق. ينطبق هذا الخيار فقط عند تفعيل سلة التسوق بتقنية AJAX، وفي حال تفعيل استخدام أكواد الخصم في إعدادات WooCommerce.','Layout of cross-sell' => 'تصميم عملية البيع المتبادل','Cross-sells displayed' => 'عرض المنتجات التكميلية','Items' => 'أغراض','Cart page optimization' => 'تحسين صفحة سلة التسوق','Give your cart the same clear, conversion-focused layout as your checkout.' => 'امنح سلة التسوق الخاصة بك نفس التصميم الواضح والمركز على التحويلات كما هو الحال في صفحة الدفع.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'قم بمطابقة تصميم سلة التسوق مع صفحة الدفع للحصول على تجربة شراء متسقة.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'حافظ على تحديث سلة التسوق باستمرار في الخلفية، ولن يتم إعادة تحميل الصفحة بالكامل عند تغيير الكميات.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'ضع أكواد الخصم، ومعلومات الشحن، والعروض الترويجية في الأماكن التي تحقق فيها أفضل النتائج.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'أبقِ ملخص الطلب مرئيًا أثناء التمرير، وأضف رموز الثقة حيث يحتاج المتسوقون إلى الاطمئنان.','Columns' => 'الأعمدة','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'أنماط عامة لخطوات الدفع، وملخص الطلب، والأقسام الأخرى. ينطبق ذلك على صفحات الدفع الأخرى، وسلة التسوق، وصفحة الشكر (بعد استلام الطلب)، وصفحات عرض الطلب.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'عند استخدام تخطيط <em>&quot;عمود واحد&quot;</em> مع قالب تصميم <em>&quot;مقسم&quot;</em> ، يظهر عمود أيمن فقط إذا كانت منطقة عناصر واجهة المستخدم في الشريط الجانبي للصفحة نشطة (شريط جانبي للدفع، أو شريط جانبي لسلة التسوق، أو شريط جانبي لاستلام الطلب). وإلا، تبقى الصفحة كعمود واحد مع أنماط التقسيم.','Split column background' => 'خلفية العمود المنقسم','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'اختر لون خلفية للعمود الثانوي في تصميم Split. اتركه فارغًا لاستخدام لون خلفية ملخص الطلب.','Page templates' => 'قوالب الصفحات','Checkout template' => 'نموذج الدفع','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'يُنصح به لتقليل عوامل التشتيت عند الدفع. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">اقرأ البحث حول التخلي عن سلة التسوق</a> .','Sticky progress bar' => 'شريط تقدم ثابت','Progress bar style' => 'نمط شريط التقدم','Order totals' => 'إجمالي الطلبات','Background color' => 'لون الخلفية','Action link' => 'رابط الإجراء','Mobile order summary' => 'ملخص طلبات الهاتف المحمول','Mobile initial state' => 'الحالة الأولية للأجهزة المحمولة','Enable editing cart items at checkout' => 'تفعيل تعديل عناصر سلة التسوق عند إتمام عملية الشراء','Allow customers to change product quantities or remove items directly at the checkout page.' => 'اسمح للعملاء بتغيير كميات المنتجات أو إزالة العناصر مباشرة في صفحة الدفع.','Cart item errors' => 'أخطاء في عناصر سلة التسوق','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'ينطبق هذا فقط عندما يتم عرض رمز القسيمة كقسم منفصل في صفحات الدفع أو سلة التسوق، وإذا تم تمكين استخدام رموز القسائم في إعدادات WooCommerce.','Coupon codes position' => 'موضع أكواد الخصم','Apply coupon button' => 'زر تطبيق القسيمة','Select style of the "apply coupon" button.' => 'اختر نمط زر &quot;تطبيق القسيمة&quot;.','Address line 2' => 'سطر العنوان 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'يتم استخدام هذا الإعداد بشكل مشترك بين قسمي الدفع والاستلام المحلي. في قسم الاستلام المحلي، يحدد هذا الإعداد أيضًا ما إذا كان مُحدد الشحن/الاستلام سيظهر داخل قسم طريقة الشحن (قبل العنوان) أو كقسم منفصل (بعده).','Customer accounts' => 'حسابات العملاء','Guest checkout' => 'مغادرة الضيوف','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'خيارات إتمام عملية الشراء كضيف، وتسجيل الدخول، وإنشاء الحساب متوفرة في صفحة إعدادات حسابات WooCommerce. تتم إدارتها هنا لتسهيل الأمر عليك، ولتتمكن من استخدام قيم مختلفة لكل ملف تعريف إعدادات.','Allow customers to checkout without an account' => 'السماح للعملاء بإتمام عملية الشراء بدون حساب','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>يُوصى بذلك</strong> حتى لا يُطلب من العملاء إنشاء حساب أو تسجيل الدخول أثناء عملية الدفع، مما قد يؤدي إلى انخفاض معدلات التحويل.','When disabled, customers must log in or create an account to complete the purchase.' => 'عند تعطيل هذه الخاصية، يجب على العملاء تسجيل الدخول أو إنشاء حساب لإتمام عملية الشراء.','Login at checkout' => 'قم بتسجيل الدخول عند إتمام عملية الشراء','Enable log-in during checkout' => 'قم بتمكين تسجيل الدخول أثناء عملية الدفع','Show a link for returning customers to log in from the checkout page.' => 'اعرض رابطًا للعملاء العائدين لتسجيل الدخول من صفحة الدفع.','Account creation' => 'إنشاء حساب','Allow customers to create an account during checkout' => 'السماح للعملاء بإنشاء حساب أثناء عملية الدفع','Customers can create an account before placing their order.' => 'يمكن للعملاء إنشاء حساب قبل تقديم طلباتهم.','Allow customers to create an account from the My account page' => 'اسمح للعملاء بإنشاء حساب من صفحة حسابي','Customers can register a new account from the My account page.' => 'يمكن للعملاء تسجيل حساب جديد من صفحة حسابي.','Username' => 'اسم المستخدم','Generate from customer\'s name' => 'يتم إنشاء الاسم من اسم العميل','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>يوصى بذلك</strong> حتى لا يُطلب من العملاء اختيار اسم مستخدم أثناء عملية الدفع، مما قد يؤدي إلى انخفاض معدلات التحويل.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'يتم إنشاء اسم المستخدم من اسم العميل، أو من عنوان البريد الإلكتروني عندما يتعذر استخدام الاسم.','Password' => 'كلمة المرور','Send password setup link' => 'أرسل رابط إعداد كلمة المرور','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>يُوصى بذلك</strong> حتى لا يُطلب من العملاء تعيين كلمة مرور أثناء عملية الدفع، مما قد يؤدي إلى انخفاض معدلات التحويل.','Customers receive an email to create their password securely.' => 'يتلقى العملاء بريدًا إلكترونيًا لإنشاء كلمة المرور الخاصة بهم بشكل آمن.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'اسمح للعملاء المسجلين بإتمام عملية الدفع دون تسجيل الدخول، واربط الطلب بحسابهم الحالي عندما تتطابق بيانات الاتصال.','Existing account message' => 'رسائل الحساب الحالي','Let customers create an account after placing their order, from the thank you page.' => 'يمكن للعملاء إنشاء حساب بعد تقديم طلباتهم، من صفحة الشكر.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'تتوفر الخيارات في هذا القسم عند تفعيل خياري &quot;إتمام عملية الدفع كضيف&quot; و&quot;مطابقة الحساب&quot;. فعّل كلا الخيارين أعلاه لضبط إعدادات إنشاء الحساب المؤجل.','Enable delayed account creation' => 'تفعيل إنشاء الحساب المؤجل','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'قم بتمكين إنشاء الحساب المؤجل عند تمكين كل من عملية الدفع كضيف ومطابقة الحساب.','Section position' => 'موقع القسم','Before customer details section' => 'قسم تفاصيل العميل قبل','After customer details section' => 'بعد أقسام تفاصيل العميل','Account creation benefits' => 'مزايا إنشاء الحساب','Leaving the field empty will display the default text.' => 'سيؤدي ترك الحقل فارغًا إلى عرض النص الافتراضي.','Inline buttons' => 'أزرار مضمنة','Required fields' => 'الحقول المطلوبة','Enable gift message fields at checkout' => 'قم بتفعيل حقول رسائل الهدايا عند إتمام عملية الشراء','Expanded gift message' => 'رسائل هدايا موسعة','Display gift message field always expanded' => 'عرض حقل رسالة الهدية موسعًا دائمًا','Gift message in order details' => 'رسالة هدية في تفاصيل الطلب','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'لا توجد تكاملات متاحة حاليًا في هذا القسم. ستظهر الخيارات المتعلقة بكل إضافة وقالب هنا فقط عند تفعيل تلك الإضافة أو القالب.','Phone fields' => 'حقول الهاتف','Field visibility' => 'رؤية الملعب','Field position' => 'موقع الملعب','Phone country code & validation' => 'رمز البلد للهاتف والتحقق منه','Country' => 'دولة','Enable country on phone fields' => 'تفعيل حقل البلد في الهاتف','Filter countries for shipping or billing' => 'قم بتصفية الدول للشحن أو الفوترة','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'قم بتقييد اختيار البلد في كل حقل من حقول الهاتف بالبلدان المسموح بها للشحن أو الفوترة في متجرك.','Validation' => 'تصديق','Enable simple validation based on country rules' => 'تفعيل التحقق البسيط بناءً على قواعد الدولة','Checks that the phone number is valid for the selected country, including country code and length.' => 'يتحقق من صحة رقم الهاتف بالنسبة للبلد المحدد، بما في ذلك رمز البلد وطول الرقم.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'يتم إجراء فحص أكثر صرامة للتأكد من أن الرقم هو رقم جوال أو خط أرضي أو أي نوع آخر مقبول في البلد المحدد. قد يتم رفض بعض الأرقام الصحيحة.','Validation types' => 'أنواع التحقق','Placeholders' => 'عناصر نائبة','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'لا توجد مفاتيح ترخيص لإدارتها حاليًا. ستظهر مفاتيح الترخيص هنا عند تفعيل إضافة أو ملحق Fluid Checkout المرخص.','Default delivery type' => 'نوع التسليم الافتراضي','Choose which delivery type will be selected by default.' => 'اختر نوع التوصيل الذي سيتم تحديده افتراضياً.','Shipping zone fields' => 'حقول منطقة الشحن','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'اختر الحقول التي ستظهر في حقول تصفية منطقة الشحن للاستلام المحلي. اتركها فارغة لعرض جميع الخيارات المتاحة.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'ستظهر هذه الحقول كفلتر لخيارات الشحن المتاحة للاستلام المحلي. قد تظهر بعض الحقول عند إتمام عملية الشراء حتى في حال عدم تحديدها هنا، وذلك إذا كانت الإضافات المتوافقة تتطلبها لتعمل بشكل صحيح.','Order shipping address' => 'عنوان شحن الطلب','Order pay page optimization' => 'تحسين صفحة دفع الطلبات','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'امنح الطلبات غير المدفوعة نفس التصميم الواضح الذي يركز على التحويل كما هو الحال في صفحة الدفع.','Optimize the layout of the order pay page for orders pending payment.' => 'قم بتحسين تصميم صفحة دفع الطلبات للطلبات التي لا تزال قيد الدفع.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'قم بمطابقة تجربة دفع الطلب مع عملية الدفع الخاصة بك للحصول على تجربة شراء متسقة.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'أضف رموزًا وشارات ثقة حيث يحتاج المتسوقون إلى الاطمئنان قبل الدفع.','Thank you page optimization' => 'تحسين صفحة الشكر','Make the thank you page and order details clearer for customers after they buy.' => 'اجعل صفحة الشكر وتفاصيل الطلب أكثر وضوحًا للعملاء بعد إتمام عملية الشراء.','Optimize the thank you page and account order details with a clearer layout.' => 'قم بتحسين صفحة الشكر وتفاصيل طلب الحساب بتصميم أكثر وضوحًا.','Show order status progress, actions, downloads, and notes where they make sense.' => 'اعرض حالة الطلب، والإجراءات، والتنزيلات، والملاحظات حيثما كان ذلك مناسباً.','Customize order details sections on email notifications.' => 'قم بتخصيص أقسام تفاصيل الطلب في إشعارات البريد الإلكتروني.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'أضف رموزًا وشارات ثقة حيث يحتاج المتسوقون إلى الاطمئنان بعد الشراء.','Email notifications' => 'إشعارات البريد الإلكتروني','Enable thank you page and order details optimizations to see more options' => 'فعّل تحسينات صفحة الشكر وتفاصيل الطلب للاطلاع على المزيد من الخيارات','Use wide layout on thank you page' => 'استخدم تصميمًا عريضًا في صفحة الشكر','These options affect the thank you page, view order details on account pages and on email notifications.' => 'تؤثر هذه الخيارات على صفحة الشكر، وعرض تفاصيل الطلب في صفحات الحساب، وعلى إشعارات البريد الإلكتروني.','Save settings' => 'حفظ الإعدادات','Docs' => 'المستندات','Cart' => 'عربة التسوق','Thank you' => 'شكرًا لك','Address autocomplete' => 'إكمال العنوان تلقائيًا','Trust badges' => 'شارات الثقة','You do not have permission to save these settings.' => 'ليس لديك إذن لحفظ هذه الإعدادات.','Invalid save request.' => 'طلب حفظ غير صالح.','Your settings have been saved.' => 'تم حفظ إعداداتك.','Saving...' => 'توفير...','Settings could not be saved. Please try again.' => 'تعذر حفظ الإعدادات. يرجى المحاولة مرة أخرى.','Dismiss notice' => 'رفض الإشعار','Open settings menu' => 'افتح قائمة الإعدادات','Close settings menu' => 'إغلاق قائمة الإعدادات','Preview' => 'معاينة','Expand preview' => 'عرض المعاينة','Collapse preview' => 'معاينة قابلة للطي','Show header and footer' => 'إظهار رأس وتذييل الصفحة','Hide header and footer' => 'إخفاء رأس وتذييل الصفحة','Page preview' => 'معاينة الصفحة','Preview viewport' => 'نافذة معاينة العرض','Tablet' => 'جهاز لوحي','Desktop' => 'سطح المكتب','Preview width' => 'عرض المعاينة','Decrease width' => 'تقليل العرض','Preview width in pixels' => 'عرض المعاينة بالبكسل','Increase width' => 'زيادة العرض','Preview as' => 'معاينة كـ','Guest' => 'ضيف','Logged in' => 'تم تسجيل الدخول','Preview page' => 'صفحة المعاينة','Expand preview for a closer look' => 'قم بتوسيع المعاينة لإلقاء نظرة أقرب','Available with %s.' => 'متوفر مع %s.','Turn them on' => 'قم بتشغيلها','Optimizations for this page are turned off. %s to preview the page.' => 'تم تعطيل تحسينات هذه الصفحة. اضغط %s لمعاينة الصفحة.','%s preview' => 'معاينة %s','Isolated session · nothing is saved' => 'جلسة معزولة · لا يتم حفظ أي شيء','Usage tracking' => 'تتبع الاستخدام','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'أرسل تقارير بيئة الموقع غير الحساسة لمساعدة Fluid Checkout على تحسين التوافق. لن تُرسل التقارير إلا بعد تفعيلها في الخيارات أدناه.','Send usage tracking reports to Fluid Checkout' => 'إرسال تقارير تتبع الاستخدام إلى Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'تساعدنا هذه التقارير على تحسين التوافق والدعم لموقعك، ويتم إرسالها أسبوعيًا عند تفعيلها.','No customer, admin user, or any other sensitive data is included in the reports.' => 'لا تتضمن التقارير أي بيانات حساسة خاصة بالعملاء أو المستخدمين الإداريين أو أي بيانات حساسة أخرى.','Basic environment info' => 'معلومات أساسية عن البيئة','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'بيانات قوائم ووردبريس، وبي إتش بي، و ووكومرس، والقوالب، والإضافات. تُضمّن هذه البيانات دائمًا عند تفعيل خاصية إعداد التقارير. تساعدنا هذه البيانات على فهم بيئة تشغيل موقعك.','Plugin settings' => 'إعدادات الإضافة','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'يرسل إعدادات إضافة Fluid Checkout للمساعدة في طلبات الدعم ويساعدنا على فهم كيفية استخدامك لإضافاتنا.','Coming soon' => 'قريباً','Sales metrics' => 'مقاييس المبيعات','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'عدد الطلبات الشهرية وإجمالي المبيعات لمدة عام قبل تثبيت Fluid Checkout وحتى اليوم. يساعدنا ذلك على فهم ما إذا كنت تحقق أرباحًا أكبر باستخدام إضافاتنا المثبتة. لا يتم إرسال أي بيانات للعملاء أو المستخدمين على الإطلاق.','Utilities' => 'المرافق','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'استخدم مكونات القائمة المنسدلة <code>TomSelect</code> بدلاً من <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect هو مكون اختيار منسدل أبسط وأقل عرضة للأخطاء من Select2، مع توفير نفس الوظائف.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'يقوم هذا المكون الإضافي بتعيين حجم الخط داخل حقول النموذج إلى 16 بكسل على الصفحات التي تم تحسينها بواسطة هذا المكون الإضافي لتجنب التكبير التلقائي عند التفاعل مع حقول النموذج على الأجهزة الصغيرة.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'قد يقوم متصفح سفاري والمتصفحات الأخرى بالتكبير التلقائي على الأجهزة المحمولة لتسهيل قراءة النص عندما يكون حجم الخط أصغر من 16 بكسل.','Enable script processing tracking on the browser console.' => 'قم بتمكين تتبع معالجة البرامج النصية في وحدة تحكم المتصفح.','Unminified assets' => 'الأصول غير المُصغّرة','Google Maps scripts' => 'برامج خرائط جوجل','Do not remove duplicate Google Maps scripts' => 'لا تقم بإزالة البرامج النصية المكررة لخرائط جوجل.','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'عند تفعيل هذا الخيار، لن تُحذف نصوص خرائط جوجل المكررة، مما قد يتسبب في حدوث أخطاء ومشاكل في الأداء. استخدم هذا الخيار فقط عند استكشاف الأخطاء وإصلاحها.','Widget areas' => 'مناطق الأدوات','Last step on mobile' => 'الخطوة الأخيرة على الهاتف المحمول','Display widgets only at last step on mobile' => 'عرض الأدوات فقط في الخطوة الأخيرة على الهاتف المحمول','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'اعرض أدوات شارة الثقة الخاصة بعملية الدفع فقط عند عرض خطوة الدفع الأخيرة على الأجهزة المحمولة','Standard' => 'معيار','VAT number field' => 'حقل رقم ضريبة القيمة المضافة','Add a VAT number field to the billing form.' => 'أضف حقل رقم ضريبة القيمة المضافة إلى نموذج الفاتورة.','Field label' => 'ملصق الحقل','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'حدد اسم حقل رقم ضريبة القيمة المضافة (أي رقم ضريبة القيمة المضافة). في المواقع الإلكترونية متعددة اللغات، يُفضل ترك هذا الحقل فارغًا وترجمة النص الأصلي.','VAT Number' => 'رقم ضريبة القيمة المضافة','EU-VAT' => 'ضريبة القيمة المضافة في الاتحاد الأوروبي','Enable the VAT number field to see more options' => 'قم بتمكين حقل رقم ضريبة القيمة المضافة لعرض المزيد من الخيارات','VAT validation' => 'التحقق من صحة ضريبة القيمة المضافة','Validate VAT number field for EU-VAT during checkout' => 'تحقق من صحة حقل رقم ضريبة القيمة المضافة لضريبة القيمة المضافة في الاتحاد الأوروبي أثناء عملية الدفع','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'يتحقق مما إذا كان رقم ضريبة القيمة المضافة المقدم هو رقم ضريبة قيمة مضافة صالح مسجل في قاعدة بيانات VIES الأوروبية (نظام تبادل معلومات ضريبة القيمة المضافة).','Shop VAT number' => 'رقم ضريبة القيمة المضافة للمتجر','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'رقم ضريبة القيمة المضافة الخاص بالمتجر المستخدم لطلب التحقق من صحة ضريبة القيمة المضافة في الاتحاد الأوروبي، ويتم طباعته على الفواتير.<br> <strong>نوصي بشدة بإضافة رقم ضريبة القيمة المضافة الخاص بمتجرك</strong> ، وإلا فقد لا تكون نتائج استشارة VIES صالحة لأغراض المحاسبة.<br> أي: <code>ATU99999999</code> أو <code>EE999999999</code> .','Reverse charge' => 'الشحنة العكسية','Apply reverse charge mechanism' => 'تطبيق آلية الشحن العكسي','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'قم بتعيين معدل الضريبة إلى الصفر واعرض عبارة &quot;التحصيل العكسي&quot; على الفواتير عندما يكون رقم ضريبة القيمة المضافة الخاص بالعميل صالحًا. قد يتطلب الأمر نصًا مختلفًا لعبارة &quot;التحصيل العكسي&quot; حسب بلد المتجر.','Same country' => 'نفس البلد','Apply reverse charge mechanism for transactions in the shop country:' => 'تطبيق آلية الاحتساب العكسي للمعاملات في بلد المتجر:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'يُمكّن من تطبيق آلية الشحن العكسي للمعاملات بين الشركات في نفس بلد المتجر.','Reverse charge exceptions' => 'استثناءات من آلية الشحن العكسي','Select additional countries to skip applying the reverse charge mechanism.' => 'حدد دولًا إضافية لتجنب تطبيق آلية الاحتساب العكسي.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'سيتم فرض الضرائب على الطلبات الواردة من هذه الدول حتى عند تقديم رقم ضريبة القيمة المضافة الصحيح.','Reverse charge label on invoices' => 'ملصق الشحن العكسي على الفواتير','Set the label of "reverse charge" on the checkout page and order details.' => 'قم بتعيين تسمية &quot;الدفع العكسي&quot; في صفحة الدفع وتفاصيل الطلب.','Reverse charge text on invoices' => 'نص &quot;الرسوم العكسية&quot; على الفواتير','Set the label of "reverse charge" text on invoices.' => 'قم بتعيين تسمية &quot;التحصيل العكسي&quot; على الفواتير.','Tax to be paid on reverse charge basis' => 'الضريبة المستحقة الدفع على أساس آلية الدفع العكسي','Company name' => 'اسم الشركة','Autocomplete company name from VAT number' => 'إكمال اسم الشركة تلقائيًا من رقم ضريبة القيمة المضافة','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'أدخل اسم شركة إصدار الفواتير بناءً على رقم ضريبة القيمة المضافة الصحيح الذي قدمه العميل.','Company name editing' => 'تحرير اسم الشركة','Allow editing of auto-filled company name' => 'السماح بتعديل اسم الشركة الذي تم ملؤه تلقائيًا','When enabled, customers can change the company name associated with the provided VAT number.' => 'عند تفعيل هذه الخاصية، يمكن للعملاء تغيير اسم الشركة المرتبط برقم ضريبة القيمة المضافة المقدم.','EU-VAT for digital goods' => 'ضريبة القيمة المضافة في الاتحاد الأوروبي على السلع الرقمية','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'اعتبارًا من 1 يناير 2015، أُدخلت تعديلات على لوائح ضريبة القيمة المضافة في الاتحاد الأوروبي فيما يتعلق بالسلع الرقمية، وتؤثر هذه التعديلات حصريًا على معاملات الشركات مع المستهلكين. يجب احتساب ضريبة القيمة المضافة على السلع الرقمية بناءً على موقع العميل، ويتعين جمع ما يثبت ذلك (عنوان بروتوكول الإنترنت وعنوان الفوترة).','Tax classes for digital goods' => 'فئات الضرائب للسلع الرقمية','Select some tax classes' => 'اختر بعض فئات الضرائب','Location evidence' => 'دليل الموقع','Collect customer\'s location evidence' => 'جمع أدلة على موقع العميل','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'يحفظ النظام عنوان IP الخاص بالعميل ويتحقق من صحته بمقارنته بعنوان الفوترة الخاص به. يجب على العميل تأكيد عنوان الفوترة الخاص به عن طريق تحديد خانة الاختيار في صفحة الدفع إذا لم يتطابق البلد المذكور في عنوان الفوترة مع عنوان IP الخاص به.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'تتم إدارة هذا الخيار في نظام الدفع السلس. <a href="%s">يمكنك تغييره في إعدادات حسابات العملاء</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'يتم إدارة هذا الخيار في نظام الدفع السلس. يمكنك تغييره من خلال نظام الدفع السلس &gt; حسابات العملاء.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'تتم إدارة هذا الخيار في نظام الدفع السلس. يتم ضبط وجهة الشحن تلقائيًا على &quot;عنوان شحن العميل&quot; عند تفعيل نظام الدفع السلس. مع ذلك، لا يزال بإمكان العملاء إدخال عناوين شحن وفواتير مختلفة أثناء عملية الدفع.<br><br> يتوفر خيار لتعيين عنوان الفوترة الافتراضي ليكون هو نفسه عنوان الشحن في <a href="%s">إعدادات Fluid Checkout</a> .','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'تتم إدارة هذا الخيار في نظام الدفع السلس. يتم ضبط وجهة الشحن تلقائيًا على &quot;عنوان شحن العميل&quot; عند تفعيل نظام الدفع السلس. مع ذلك، لا يزال بإمكان العملاء إدخال عناوين شحن وفواتير مختلفة أثناء عملية الدفع.<br><br> يتوفر خيار لتعيين عنوان الفوترة الافتراضي ليكون هو نفسه عنوان الشحن في WooCommerce &gt; الإعدادات &gt; الدفع السلس.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'تم نقل هذه الإعدادات إلى لوحة تحكم ووردبريس &gt; Fluid Checkout &gt; الإعدادات.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'تم إيقاف علامة تبويب إعدادات WooCommerce هذه وسيتم إزالتها في Fluid Checkout 6.0.','Go to settings page' => 'انتقل إلى صفحة الإعدادات','Hide this tab permanently' => 'إخفاء هذه الصفحة نهائياً','Site report preview' => 'معاينة تقرير الموقع','This is the data that would be included in the next site environment report based on your current settings.' => 'هذه هي البيانات التي سيتم تضمينها في تقرير بيئة الموقع التالي بناءً على إعداداتك الحالية.','Loading report preview...' => 'جارٍ تحميل معاينة التقرير...','Could not load the site report preview. Try again.' => 'تعذر تحميل معاينة تقرير الموقع. حاول مرة أخرى.','Could not send the site report. Try again.' => 'تعذر إرسال تقرير الموقع. حاول مرة أخرى.','Site report sent successfully.' => 'تم إرسال تقرير الموقع بنجاح.','Enable and send now' => 'فعّل الخدمة وأرسل الآن','Close' => 'يغلق','A site report request is already in progress. Try again in a moment.' => 'طلب تقرير الموقع قيد المعالجة حاليًا. حاول مرة أخرى بعد قليل.','Site environment reporting is disabled.' => 'تم تعطيل خاصية الإبلاغ عن بيئة الموقع.','No site report data is available to send.' => 'لا تتوفر بيانات تقرير الموقع لإرسالها.','This site domain cannot send environment reports (local or development domains are excluded).' => 'لا يمكن لنطاق هذا الموقع إرسال تقارير البيئة (يتم استبعاد النطاقات المحلية أو نطاقات التطوير).','A site report was sent recently. Try again later.' => 'تم إرسال تقرير عن الموقع مؤخراً. حاول مرة أخرى لاحقاً.','The site report could not be sent. Try again later.' => 'تعذر إرسال تقرير الموقع. حاول مرة أخرى لاحقاً.','Site environment reporting is not available.' => 'لا تتوفر تقارير عن بيئة الموقع.','No site report data is available for the selected settings.' => 'لا تتوفر بيانات تقرير الموقع للإعدادات المحددة.','You are not allowed to manage site reports.' => 'لا يُسمح لك بإدارة تقارير الموقع.','PRO feature' => 'ميزة احترافية','Other plugins' => 'إضافات أخرى','Get only this add-on &mdash; %s' => 'احصل على هذه الإضافة فقط — %s','Install add-on' => 'تثبيت الإضافة','Upgrade to PRO &mdash; %s' => 'الترقية إلى الإصدار الاحترافي — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">احصل على %2$s</a> لفتح هذه الخيارات.','Add-on' => 'إضافة','View documentation' => 'عرض الوثائق','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'تتطلب الطلبات تسجيل دخول مستخدم ووردبريس. احذف user_id لاستخدام بيانات المستخدم الحالي، أو مرر user_id لاستهداف حساب آخر عندما يكون بإمكان المُستدعي تعديل بيانات ذلك المستخدم (صلاحية edit_user). تُرجع الطلبات غير المُصادق عليها fc_api_forbidden. يُرجع user_id غير صالح fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 مع { &quot;data&quot;: { ... } } عندما يقوم المعالج بإرجاع حمولة.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 مع { &quot;success&quot;: true } عندما لا يكون هناك حمولة (على سبيل المثال DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'في حالة الفشل، يتم إرجاع بيانات JSON الخاصة بخطأ REST في ووردبريس من WP_Error (الرمز، الرسالة، بيانات الحالة). تستخدم رموز الاتصال البادئة fc_api_*.','Forbidden access.' => 'ممنوع الدخول.','Target user was not found.' => 'لم يتم العثور على المستخدم المستهدف.','This feature is not available.' => 'هذه الميزة غير متوفرة.','A required address field is missing.' => 'حقل العنوان المطلوب مفقود.','Postcode or ZIP is invalid.' => 'الرمز البريدي أو رمز المنطقة البريدية غير صالح.','Phone number is invalid.' => 'رقم الهاتف غير صالح.','State or county is invalid.' => 'الولاية أو المقاطعة غير صالحة.','Country is invalid or has no address fields.' => 'البلد غير صالح أو لا يحتوي على حقول عنوان.','The request could not be processed.' => 'تعذر معالجة الطلب.','Back to previous step' => 'العودة إلى الخطوة السابقة','Skip to settings' => 'انتقل إلى الإعدادات','Start over and return to the first guided setup step' => 'ابدأ من جديد وارجع إلى خطوة الإعداد الأولى الموجهة','Start over' => 'ابدأ من جديد','Please complete all sub-steps before continuing.' => 'يرجى إكمال جميع الخطوات الفرعية قبل المتابعة.','Expand' => 'يوسع','Collapse' => 'ينهار','Skip' => 'يتخطى','Mark as complete' => 'ضع علامة كمكتمل','Mark as incomplete' => 'ضع علامة على أنها غير مكتملة','View full-size image: %s' => 'عرض الصورة بالحجم الكامل: %s','Full-size setup guide image' => 'صورة دليل الإعداد بالحجم الكامل','Close image' => 'إغلاق الصورة','Fluid Checkout Guided Setup' => 'إعداد موجه لعملية الدفع السلسة','Welcome' => 'مرحباً','Explore your checkout' => 'استكشف صفحة الدفع الخاصة بك','All set' => 'جاهز تمامًا','You do not have permission to access this page.' => 'ليس لديك إذن بالوصول إلى هذه الصفحة.','Go to step %1$d: %2$s' => 'انتقل إلى الخطوة %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'يساعدك هذا الإعداد الموجه على التعرف على نظام الدفع السلس (Fluid Checkout). الخطوات المذكورة أدناه هي خطوات مؤقتة.','Continue to the next step when you are ready.' => 'انتقل إلى الخطوة التالية عندما تكون مستعدًا.','Open your store checkout to see Fluid Checkout in action.' => 'افتح صفحة الدفع في متجرك لتشاهد نظام الدفع السلس أثناء العمل.','View checkout page' => 'عرض صفحة الدفع','You can return to Fluid Checkout settings to continue configuring your store.' => 'يمكنك العودة إلى إعدادات Fluid Checkout لمتابعة تهيئة متجرك.','Review checkout and cart settings' => 'راجع إعدادات الدفع وسلة التسوق','Explore add-ons from the dashboard' => 'استكشف الإضافات من لوحة التحكم','Finish & go to settings' => 'أنهِ العملية وانتقل إلى الإعدادات','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'قم بتحديث خيار رؤية حقل رقم الهاتف الخاص بالفواتير من القيمة القديمة ليتوافق مع معايير WooCommerce.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'قم بتحديث خيار رؤية حقل هاتف الشحن من القيمة القديمة ليتوافق مع معايير WooCommerce.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'انسخ إعداد لون خلفية ملخص الطلب إلى خيار لون خلفية العمود الثانوي في تصميم Split الجديد.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'يتم تعطيل ميزة حقول الاختيار المحسّنة دائمًا عند استخدام إضافة Biteship.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'عند استخدام إضافة German Market، يكون موضع زر &quot;إتمام الطلب&quot; دائمًا &quot;أسفل ملخص الطلب&quot;. تتطلب هذه الإضافة عرض زر &quot;إتمام الطلب&quot; ومربعات الاختيار القانونية أسفل ملخص الطلب.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'عند استخدام إضافة Germanized لـ WooCommerce، يتم ضبط موضع زر &quot;إتمام الطلب&quot; دائمًا على &quot;أسفل ملخص الطلب&quot;. تتطلب هذه الإضافة عرض زر &quot;إتمام الطلب&quot; ومربعات الاختيار القانونية أسفل ملخص الطلب.','Edit pickup locations' => 'تعديل مواقع الاستلام','Use local pickup label from WooCommerce settings' => 'استخدم ملصق الاستلام المحلي من إعدادات ووكومرس','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'عند تفعيل خيار الاستلام، يتطابق عنوانه في صفحة الدفع مع العنوان المُحدد في إعدادات موقع الاستلام في WooCommerce. أما عند تعطيله، فيستخدم النص القابل للترجمة &quot;الاستلام المحلي&quot; من Fluid Checkout.','Button label for applying coupon codesApply' => 'يتقدم','Checkout step titleContact' => 'اتصال','Checkout step titleShipping' => 'شحن','Checkout step titleBilling' => 'الفواتير','Checkout step titlePayment' => 'قسط','Checkout substep change link labelChange' => 'يتغير','Checkout substep save link labelSave changes' => 'حفظ التغييرات','Substep review textNone.' => 'لا أحد.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'لم يتم اختيار أي صورة.','Settings sectionCart' => 'العربة','Settings sectionOrder pay' => 'طلب الدفع','Settings sectionThank you' => 'شكرًا لك','Settings section titleIntegrations' => 'التكاملات','Settings section titleLicense keys' => 'مفاتيح الترخيص','Captcha positionBefore place order section' => 'قسم قبل وضع الطلب','Captcha positionBefore place order button' => 'زر قبل وضع الطلب','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'يغلق','Log in link label at checkout contact stepLog in' => 'تسجيل الدخول','Log in separator label at for when guest checkout is disabledOr continue below' => 'أو تابع أدناه','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'أو استمر كضيف','Clear image selection on admin pages.Remove image' => 'إزالة الصورة','shipping packagesShipping %d' => 'الشحن %d','shipping packagesShipping' => 'شحن','Used as fallback for "Proceed to next step" button labelnext step' => 'الخطوة التالية','Substep review checkbox valueYes' => 'نعم','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'جون','Dummy customer last name in the admin previewDoe' => 'أنثى الأيل','Dummy customer company in the admin previewExample Company' => 'مثال على شركة','Dummy customer street address in the admin preview123 Main Street' => '123 شارع رئيسي','Dummy customer city in the admin previewAnytown' => 'أي تاون','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'يرجى ترك الطرد عند الباب الأمامي.','Dummy product name in the admin previewBeanie' => 'قبعة صغيرة','Dummy product name in the admin previewCap' => 'كاب','Dummy product name in the admin previewT-Shirt' => 'تي شيرت','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'لقد استلمنا طلبك وسنرسل لك تحديثًا عند شحنه.','Dummy download in the admin previewUser guide' => 'دليل المستخدم','Google Places API versionsPlaces API (New)' => 'واجهة برمجة تطبيقات الأماكن (جديدة)','Google Places API versionsPlaces API (Legacy)' => 'واجهة برمجة تطبيقات الأماكن (القديمة)','Brasil API versionsVersion 1' => 'الإصدار 1','Brasil API versionsVersion 2' => 'الإصدار 2','Delayed account creation benefits placeholder text✔ Checkout faster next time
